from rest_framework.throttling import SimpleRateThrottle

class UserOrIPRateThrottle(SimpleRateThrottle):
    """Scope por settings; key = user.pk si hay sesión, si no IP — un
    usuario autenticado NO salta la cuota de endpoints AllowAny con
    efectos laterales (mails, tokeninfo, rotación)."""
    def get_cache_key(self, request, view):
        if request.user and request.user.is_authenticated:
            ident = f'u{request.user.pk}'
        else:
            ident = self.get_ident(request)
        return self.cache_format % {'scope': self.scope, 'ident': ident}

class PasswordResetRateThrottle(UserOrIPRateThrottle):
    scope = 'password_reset'
